mapper.select:
select *
  from rule_version
 where rule_id = #{ruleId}
   and version = #{version}

mapper.update:
update rule_version
   set status = 'DISABLED',
       disabled_at = #{disabledAt},
       auto_delete_at = #{autoDeleteAt},
       disabled_from_status = #{disabledFromStatus}
 where rule_id = #{ruleId}
   and version = #{version}

