select count(*)
  from rule
 where id = #{ruleId}
   and application_id = #{applicationId}
   and environment_id = #{environmentId}

select count(*)
  from rule
 where id = #{ruleId}
   and application_id = #{applicationId}
   and environment_id = #{environmentId}
   and status = 'ENABLED'
   and exists (
       select 1
         from rule_version rv
        where rv.rule_id = rule.id
          and rv.status = 'ENABLED'
   )

select count(*)
  from rule_version
 where rule_id = #{ruleId}
   and version = #{version}
   and status = 'ENABLED'
